import type { CoursePracticeQuestion, StructuredLessonSection } from "./cisc1115Course.ts";
import { validateClassroomJava, type ClassroomSample, type ClassroomSpec } from "../classroomJavaValidation.ts";

const lines=(s:string)=>s.trim().replace(/\r/g,"").split("\n").map(s=>s.trimEnd()).join("\n");
const trace=(id:string,title:string,code:string,answer:string,hint:string,level:CoursePracticeQuestion["level"]="Apply",prompt="What is the exact output?"):CoursePracticeQuestion=>({id,level,title,kind:"Trace output",prompt,code,answer,hint,success:"Correct. You followed the values and the method results.",placeholder:"Type the requested result",multiline:answer.includes("\n"),validate:s=>lines(s)===answer});
const choice=(id:string,title:string,prompt:string,answer:string,others:string[],hint:string):CoursePracticeQuestion=>{
  const options=[answer,...others],at=[...id].reduce((a,c)=>a+c.charCodeAt(0),0)%options.length;
  return {id,title,prompt,answer,options:[...options.slice(at),...options.slice(0,at)],hint,level:"Warm-up",kind:"Multiple choice",success:"Correct. The choice matches the Java rule.",placeholder:"Choose one answer",validate:s=>s.trim()===answer};
};
export const classroomValidationFixtures = new Map<string, {spec:ClassroomSpec;samples:ClassroomSample[]}>();
const write=(id:string,title:string,prompt:string,answer:string,spec:ClassroomSpec,samples:ClassroomSample[],hint:string,code?:string):CoursePracticeQuestion=>{
  classroomValidationFixtures.set(id,{spec,samples});
  return {id,title,prompt,answer,code,hint,level:spec.className?"Challenge":"Apply",kind:spec.className?"Complete Java program":"Write Java code",multiline:true,productionStage:spec.className?5:code?3:4,auditRequirements:["Known classroom tools","Results across varied cases"],success:"Your code meets the behavior for the tested values and boundaries.",placeholder:spec.className?"Write the complete Java source file":"Write the requested Java statements",validate:s=>validateClassroomJava(s,spec,samples)};
};
const program=(name:string,body:string,file=false)=>`${file?"import java.io.File;\nimport java.io.PrintWriter;\nimport java.io.FileNotFoundException;\n":""}import java.util.Scanner;\n\npublic class ${name} {\n    public static void main(String[] args)${file?" throws FileNotFoundException":""} {\n${body.split("\n").map(s=>"        "+s).join("\n")}\n    }\n}`;
const seeded=(random:number)=>Array(16).fill(random) as number[];
const resultCases=(values:Record<string,number|boolean|string>[],f:(v:Record<string,number|boolean|string>)=>number|string|boolean)=>values.map(v=>({values:v,result:f(v)}));

export const methodArgumentsSection:StructuredLessonSection={id:"midterm-method-arguments",eyebrow:"Call a tool with values",title:"Methods, Parameters, Arguments, and Return Values",lead:"A method performs a named job. Java already supplies the Math and String methods in this part of the course. A parameter is an input slot in the method's definition; an argument is the actual value you supply in a call. You are learning to call these tools before the later unit on writing your own methods.",concepts:[{label:"Arguments",detail:"Math.pow(3, 2) supplies 3 and 2. Math.pow(side, 2) evaluates side before the call."},{label:"Parameters",detail:"pow has two numeric input slots: a base and an exponent. sqrt has one numeric input slot."},{label:"Return value",detail:"Math.pow(3, 2) returns double 9.0. You can store, print, compare, or pass that result to another method."},{label:"Class versus object calls",detail:"Math.sqrt(25) calls a tool on Math. Later, text.length() calls a tool on the String object referenced by text."}],examples:[{label:"Follow the call",code:"double side = 3.0;\ndouble area = Math.pow(side, 2);\nSystem.out.println(area); // 9.0",note:"side and 2 are arguments; the returned double becomes area."},{label:"Use a returned value as an argument",code:"double distance = Math.sqrt(Math.pow(3, 2) + Math.pow(4, 2));\nSystem.out.println(distance); // 5.0",note:"The inner calls return 9.0 and 16.0; their sum is the argument to sqrt."}],rules:["Count arguments and match their types to the method's inputs.","The return type affects assignment and the printed value.","A method call does not require defining a new method."]};
export const randomIntegersSection:StructuredLessonSection={id:"midterm-random-integers",eyebrow:"Scale, then convert, then shift",title:"Generating Random Integers",lead:"Math.random() takes no arguments and returns a double r with 0.0 <= r < 1.0. To get a uniform integer range, multiply by the number of choices, cast the scaled result to int, and shift if the first allowed integer is not zero. Parentheses decide when the cast happens.",concepts:[{label:"0, 1, or 2",detail:"(int) (Math.random() * 3): 3 is excluded before the cast."},{label:"1 through 6",detail:"(int) (Math.random() * 6) + 1."},{label:"low through high, inclusive",detail:"There are high - low + 1 choices; use (int) (Math.random() * (high - low + 1)) + low."},{label:"Casting too early",detail:"(int) Math.random() is always zero because the original value is below 1."}],examples:[{label:"Three choices for a game",code:"int computerMove = (int) (Math.random() * 3);\n// 0 = rock, 1 = paper, 2 = scissors",note:"This is the range meant by the homework's parenthetical 0, 1, 2."},{label:"Trace with a supplied random value",code:"double sample = 0.74;\nint roll = (int) (sample * 6) + 1;\nSystem.out.println(roll); // 5",note:"0.74 * 6 = 4.44, the cast gives 4, and +1 gives 5."}],rules:["Multiply before casting.","Keep the upper endpoint excluded until the shift.","Math.round is not the same operation as truncating equal-width intervals."]};
export const triangleProgram=program("Trigonometry",`Scanner input = new Scanner(System.in);
double x1 = input.nextDouble();
double y1 = input.nextDouble();
double x2 = input.nextDouble();
double y2 = input.nextDouble();
double x3 = input.nextDouble();
double y3 = input.nextDouble();
double distA = Math.sqrt(Math.pow(x2 - x3, 2) + Math.pow(y2 - y3, 2));
double distB = Math.sqrt(Math.pow(x1 - x3, 2) + Math.pow(y1 - y3, 2));
double distC = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
double angleA = Math.acos((distB * distB + distC * distC - distA * distA) / (2 * distB * distC));
double angleB = Math.acos((distA * distA + distC * distC - distB * distB) / (2 * distA * distC));
double angleC = Math.acos((distA * distA + distB * distB - distC * distC) / (2 * distA * distB));
System.out.println(Math.toDegrees(angleA));
System.out.println(Math.toDegrees(angleB));
System.out.println(Math.toDegrees(angleC));`);
export const geometrySection:StructuredLessonSection={id:"midterm-math-formulas",eyebrow:"Turn a supplied formula into code",title:"Formulas, Radians, and the Triangle Example",lead:"The class triangle program reads three vertices, calculates the three side lengths, then uses the law of cosines to obtain angles. The new Java tools are Math.acos, which returns radians, and Math.toDegrees, which converts radians into degrees. The formulas are supplied here; the programming job is preserving their grouping and following the data.",concepts:[{label:"Distance",detail:"Between (x1,y1) and (x2,y2): sqrt((x2-x1)^2 + (y2-y1)^2). Java exponentiation uses Math.pow, not ^."},{label:"Opposite side labels",detail:"A joins points 2 and 3; B joins 1 and 3; C joins 1 and 2."},{label:"Angle at point 1",detail:"acos((B*B + C*C - A*A) / (2*B*C)), then convert to degrees. The other angles follow the same opposite-side pattern."},{label:"Math return types",detail:"sqrt, pow, acos, toDegrees, floor, ceil and random return double. round(double) returns a whole-number long; printing it displays a whole number."}],examples:[{label:"Translate grouping faithfully",code:"// a = b + sqrt((c + 3) / (2 + d)) - e\ndouble a = b + Math.sqrt((c + 3) / (2 + d)) - e;",note:"The displayed midterm formula puts -e outside the radical; preserve that placement."},{label:"Class example: all three triangle angles",code:triangleProgram,note:"Assume valid, nondegenerate triangles. For (0,0), (3,0), (0,4), the angles at points 1, 2, 3 are approximately 90, 53.13, 36.87 degrees. This is equivalent to the class file's algebraic form."}],rules:["Compute and store intermediate results when they clarify the formula.","acos gives an angle in radians; convert before labeling it degrees.","Use decimal arithmetic for ratios.","Keep a method's whole argument inside its parentheses."]};

