export const characterCodesSection:StructuredLessonSection={id:"midterm-char-codes",eyebrow:"A character has a numeric code",title:"Character Codes, Casts, and Arithmetic",lead:"A Java char is a 16-bit UTF-16 code unit. For the basic characters used here, '0' through '9' have codes 48 through 57, 'A' through 'Z' have codes 65 through 90, and 'a' through 'z' have codes 97 through 122. Standard ASCII covers codes 0 through 127. Character arithmetic uses numeric codes, and its result is normally int.",concepts:[{label:"Numeric cast",detail:"(int) 'A' gives 65; (char) 66 gives 'B'."},{label:"Character arithmetic",detail:"'2' + '3' adds 50 + 51, giving int 101. With a String operand, + instead joins text."},{label:"Constant expressions",detail:"char c = 'A' + 1 compiles because that constant int value fits char. With a variable, use an explicit cast: char next = (char) (c + 1)."},{label:"Character tools",detail:"Character.isDigit(c), isLetter(c), isUpperCase(c), isLowerCase(c) return boolean. Character.toUpperCase(c) returns char."}],examples:[{label:"Separate printed text from the code",code:"char letter = 'A';\nSystem.out.println(letter);       // A\nSystem.out.println((int) letter); // 65\nSystem.out.println(letter + 1);   // 66\nSystem.out.println((char) (letter + 1)); // B",note:"A char and the numeric result of char arithmetic print differently."},{label:"Retrieve a digit's value",code:"char digit = '7';\nint value = digit - '0';\nSystem.out.println(value); // 7",note:"Subtracting the code for '0' gives the numeric digit value."}],rules:["Single quotes mean char; double quotes mean String.","The code for the digit '0' is 48 (\\u0030), not the code for 'a'.","A variable-based numeric result needs a cast before storing it back in char."]};
export const referenceSection:StructuredLessonSection={id:"midterm-string-references",eyebrow:"Content and identity answer different questions",title:"String References and Returned Strings",lead:"A String variable references an object. Assigning String second = first makes both variables reference the same object. == compares that identity; equals compares the text. Transformations return a String result, so remember to store the returned text if you want to use it later.",concepts:[{label:"Shared reference",detail:"second = first shares a String object; it does not create an independent copy."},{label:"Content equality",detail:"Use equals for matching text and equalsIgnoreCase when the behavior ignores capitalization."},{label:"New text",detail:"first = first.toLowerCase() changes which result first refers to; it does not rewrite the original object."}],examples:[{label:"Reassignment does not change the other variable",code:"String first = \"Hello\";\nString second = first;\nfirst = first.toLowerCase();\nSystem.out.println(first);  // hello\nSystem.out.println(second); // Hello\nSystem.out.println(first.equals(second)); // false",note:"Follow each reference after the returned value is assigned."},{label:"Use the return value",code:"String word = \"Hello\";\nword.toUpperCase();\nSystem.out.println(word); // Hello\nword = word.toUpperCase();\nSystem.out.println(word); // HELLO",note:"Calling a transformation and discarding its result leaves word unchanged."}]};
export const scannerTextSection:StructuredLessonSection={id:"midterm-scanner-text",eyebrow:"Choose tokens or whole lines",title:"Scanner Text and Character Input",lead:"next() reads one whitespace-delimited token; nextLine() reads the rest of the current line, excluding the line ending. nextInt and nextDouble consume their token but leave following whitespace, including a newline. To read a char, read a String and select a character with charAt.",concepts:[{label:"Two separate names",detail:"Two next() calls can read Alice Smith into first and last."},{label:"A multiword place",detail:"Use nextLine() to keep Brooklyn College together."},{label:"After a number",detail:"After nextInt(), a nextLine() may return the empty remainder of that numeric line; consume it before reading the next whole line."},{label:"A character",detail:"char move = input.next().charAt(0); the result of next() is the receiver of charAt(0)."}],examples:[{label:"Keep a full name",code:"Scanner input = new Scanner(System.in);\nString name = input.nextLine();\nSystem.out.println(\"Hello, \" + name);",note:"Input Alice Smith prints Hello, Alice Smith."},{label:"Read a number, then a whole line",code:"int age = input.nextInt();\ninput.nextLine();\nString name = input.nextLine();",note:"For 20 followed by Enter, then Alice Smith followed by Enter, the discarded remainder is empty and name contains both words."}],rules:["Choose the input method from the required behavior.","Scanner reads have return types: next/nextLine return String, nextInt returns int, nextDouble returns double.","Validate textual options with String content methods."]};

