export const conversionProgram=program("Conversion","Scanner input = new Scanner(System.in);\ndouble meters = input.nextDouble();\nString unit = input.next();\nif (unit.equals(\"inches\")) { System.out.println(meters * 39.37 + \" inches\"); }\nelse if (unit.equals(\"feet\")) { System.out.println(meters * 3.28 + \" feet\"); }\nelse if (unit.equals(\"miles\")) { System.out.println(meters * 0.000621 + \" miles\"); }\nelse { System.out.println(\"Invalid conversion\"); }");
export const conversionQuestion=write("mid-conversion-program","Class Practice: Conversion Menu","Write Conversion.java. Read a distance in meters and a one-word choice: inches, feet, or miles. Multiply by 39.37, 3.28, or 0.000621 respectively and print VALUE UNIT. For any other choice, print Invalid conversion and no converted value. Choices are case-sensitive. Optional prompts may precede input.",conversionProgram,{className:"Conversion"},[{input:"21 feet",output:"68.88 feet"},{input:"4 centimeters",output:"Invalid conversion"},{input:"2 inches",output:"78.74 inches"},{input:"1000 miles",output:"0.621 miles"},{input:"0 feet",output:"0.0 feet"}],"String equality chooses a branch; the selected factor changes the numeric result.");
export const bookQuestion=write("mid-book-pricing","Class Practice: Book Type and Happy Hour","Given String bookType (hardcover or softcover) and int time (0 through 23), print the book price with a dollar sign. Hardcover is $2; softcover is $1. From hour 16 inclusive to 19 exclusive, all prices are halved. Print $1 for discounted hardcover, $0.50 for discounted softcover, $2 or $1 otherwise.","if (bookType.equals(\"hardcover\")) {\n    if (time >= 16 && time < 19) { System.out.println(\"$1\"); } else { System.out.println(\"$2\"); }\n} else {\n    if (time >= 16 && time < 19) { System.out.println(\"$0.50\"); } else { System.out.println(\"$1\"); }\n}",{types:{bookType:"String",time:"int"}},["hardcover","softcover"].flatMap(bookType=>[15,16,18,19,20].map(time=>({values:{bookType,time},output:time>=16&&time<19?bookType==="hardcover"?"$1":"$0.50":bookType==="hardcover"?"$2":"$1"}))),"Check both book type and interval boundaries. Several branch structures can meet these rules.");
export const shippingProgram=program("Shipping","Scanner input = new Scanner(new File(\"package.txt\"));\ndouble weight = input.nextDouble();\nint zone = input.nextInt();\nint rush = input.nextInt();\ninput.close();\ndouble fee = weight;\nif (zone != 1) { fee += 5; }\nif (zone == 3) { fee *= 1.5; }\nif (rush == 1) { fee += 20; }\nSystem.out.println(fee);",true);
export const shippingQuestion=write("mid-shipping-program","Class Practice: Shipping Rules","Write Shipping.java. package.txt has a double weight in pounds, an int zone (1, 2, 3), and int rush flag (0, 1). The fee starts at $1 per pound. Add $5 outside zone 1, then multiply that subtotal by 1.5 for zone 3. Finally add $20 for rush. Print the fee as one number, include file setup, and close the file Scanner. All input values have the stated valid types/ranges.",shippingProgram,{className:"Shipping",requireClose:true,numericOutput:true},[{weight:10,zone:3,rush:0},{weight:13,zone:1,rush:1},{weight:5,zone:3,rush:0},{weight:33,zone:3,rush:1},{weight:3.5,zone:1,rush:0},{weight:8,zone:2,rush:1},{weight:0,zone:2,rush:0}].map(v=>({files:{"package.txt":`${v.weight} ${v.zone} ${v.rush}`},output:String((v.zone===3?(v.weight+5)*1.5:v.weight+(v.zone===1?0:5))+(v.rush?20:0))})),"Preserve which subtotal the multiplier applies to; the rush fee is added last.");
export const madLibsProgram=program("MadLibs","Scanner input = new Scanner(System.in);\nString number = input.nextLine();\nString noun = input.nextLine();\nString verb = input.nextLine();\nString food = input.nextLine();\nString place = input.nextLine();\nPrintWriter output = new PrintWriter(\"story.txt\");\noutput.println(\"Today I attended CISC \" + number + \". We learned about \" + noun + \". My computer began to \" + verb + \". I ate \" + food + \". This weekend I will visit \" + place + \".\");\noutput.close();",true);
export const madLibsQuestion=write("mid-madlibs-program","Class Practice: Mad Libs to a File","Write MadLibs.java. Read five whole lines: a course number, plural noun, verb phrase, food, and place. Insert them into this exact story and write it to story.txt: Today I attended CISC NUMBER. We learned about NOUN. My computer began to VERB. I ate FOOD. This weekend I will visit PLACE. Multiword phrases must remain intact. Include file-opening setup and close the writer; optional prompts may precede input.",madLibsProgram,{className:"MadLibs",requireClose:true},[{number:"1115",noun:"arrays",verb:"scream",food:"spaghetti",place:"the DMV"},{number:"21942",noun:"cloud computers",verb:"run very slowly",food:"spicy noodles",place:"Brooklyn College"}].map(v=>({input:[v.number,v.noun,v.verb,v.food,v.place].join("\n")+"\n",outputFiles:{"story.txt":`Today I attended CISC ${v.number}. We learned about ${v.noun}. My computer began to ${v.verb}. I ate ${v.food}. This weekend I will visit ${v.place}.`}})),"Select reads that keep each entire phrase, then assemble the fixed story.");
export const rpsProgram=program("RockPaperScissors","Scanner input = new Scanner(System.in);\nint computer = (int) (Math.random() * 3);\nString move = input.next();\nif (!move.equals(\"rock\") && !move.equals(\"paper\") && !move.equals(\"scissors\")) { System.out.println(\"Invalid input\"); return; }\nString computerName;\nif (computer == 0) { computerName = \"rock\"; } else if (computer == 1) { computerName = \"paper\"; } else { computerName = \"scissors\"; }\nSystem.out.println(\"I play \" + computerName);\nif (move.equals(computerName)) { System.out.println(\"Draw!\"); }\nelse if ((move.equals(\"rock\") && computer == 2) || (move.equals(\"paper\") && computer == 0) || (move.equals(\"scissors\") && computer == 1)) { System.out.println(\"You win!\"); }\nelse { System.out.println(\"I win!\"); }");
const moves=["rock","paper","scissors"];
export const rpsQuestion=write("mid-rps-program","Class Practice: One Game Round","Write RockPaperScissors.java. Uniformly generate 0, 1, or 2 (rock, paper, scissors). Read the user's case-sensitive move. For legal moves print I play MOVE, then You win!, I win!, or Draw!. Rock beats scissors, scissors beats paper, and paper beats rock. For any illegal move, print only Invalid input. Optional prompts may precede input.",rpsProgram,{className:"RockPaperScissors"},moves.flatMap((move,i)=>[0,.1,1/3-1e-8,1/3,.4,2/3-1e-8,2/3,.9,.999999].map(r=>{const computer=Math.floor(3*r);return {input:move,random:seeded(r),output:`I play ${moves[computer]}\n${i===computer?"Draw!":(i+2)%3===computer?"You win!":"I win!"}`};})).concat(["xyz","Rock","stone"].map(move=>({input:move,random:seeded(.4),output:"Invalid input"}))),"Validate first, distinguish the computer's code from its name, then consider draw/win/loss.");
export const textDecisionSection:StructuredLessonSection={id:"midterm-text-decisions",eyebrow:"Use known tools together",title:"Text Menus, Ranges, and Game Decisions",lead:"Class problems now combine String input with the decisions you already know. A text menu needs equals or equalsIgnoreCase, a pricing window needs precise boundaries, and a game needs validation before outcome rules. Decide which facts affect each output before choosing nesting or a combined Boolean.",examples:[{label:"Class practice: a textual conversion menu",code:conversionProgram,note:"Unsupported units produce one error result. The task can be implemented by several valid branch structures."},{label:"Separate validity from a game outcome",code:"boolean valid = move.equals(\"rock\") || move.equals(\"paper\") || move.equals(\"scissors\");\nif (!valid) {\n    System.out.println(\"Invalid input\");\n} else {\n    // Evaluate draw, win, and loss here.\n}",note:"An invalid move is not a draw. Full-program practice asks you to design the legal outcome logic."}],rules:["Use content comparison for menu words.","State whether capitalization matters.","Test both ends of a time interval.","For Rock/Paper/Scissors, check all nine legal pairs and invalid input."]};

