export const triangleQuestion=write("mid-triangle-program","Class Practice: Three Triangle Angles","Write Trigonometry.java. Read x1, y1, x2, y2, x3, y3 as doubles. Assume valid, nondegenerate triangles. Print the angles at points 1, 2, 3 in degrees, one per line (full precision or at least two decimal places). Side A joins 2-3; B joins 1-3; C joins 1-2. Distance formula: sqrt((x2-x1)^2+(y2-y1)^2). Angle opposite A: acos((B*B+C*C-A*A)/(2*B*C)); rotate the opposite-side labels for the other two angles. Optional prompts may precede input.",triangleProgram,{className:"Trigonometry",numericOutput:true,numericTolerance:.005},triangles.map(p=>{const A=Math.hypot(p[2]-p[4],p[3]-p[5]),B=Math.hypot(p[0]-p[4],p[1]-p[5]),C=Math.hypot(p[2]-p[0],p[3]-p[1]);return {input:p.join(" "),output:[Math.acos((B*B+C*C-A*A)/(2*B*C)),Math.acos((A*A+C*C-B*B)/(2*A*C)),Math.acos((A*A+B*B-C*C)/(2*A*B))].map(r=>String(r*180/Math.PI)).join("\n")};}),"The formula is given; your job is matching each side, preserving the ratio and converting the returned radians.");

