const nestedTrace=`int a = 12;
int b = 50;
double c = 0;
if (a % 2 == 1) {
    if (b > 10) { c = b + 2; b += 2; }
    else { c = a * 2; b--; }
} else {
    if (b != 50) { c = b + 1; b -= 1; }
    else if (b >= 50) { c = a - 1; a -= 1; }
    a *= 2;
}
if (a % 2 == 1) { b = 0; } else { b = 1; }
System.out.println(a + " " + b + " " + c);`;
